-- Rubros (plan: docs/planesdemodulos/plan-rubros-fichas-ordenes-trabajo.md, etapa 1).
-- Catálogo de plataforma administrado desde /admin/rubros + rubro y módulos
-- de cada negocio en tenant_settings.

-- Negocio: rubro elegido y módulos que usa. modulesConfigured = false (todos
-- los negocios existentes) mantiene el menú completo como hasta ahora.
ALTER TABLE "tenant_settings"
  ADD COLUMN "businessTemplateKey" TEXT,
  ADD COLUMN "businessTemplateVersion" INTEGER,
  ADD COLUMN "businessTemplatePending" BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN "modulesConfigured" BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN "enabledModules" TEXT[] DEFAULT ARRAY[]::TEXT[];

CREATE TABLE "business_templates" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "family" TEXT NOT NULL,
    "iconKey" TEXT NOT NULL,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "config" JSONB NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "business_templates_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "business_templates_key_key" ON "business_templates"("key");
CREATE INDEX "business_templates_isActive_family_sortOrder_idx" ON "business_templates"("isActive", "family", "sortOrder");

CREATE TABLE "business_template_versions" (
    "id" TEXT NOT NULL,
    "templateId" TEXT NOT NULL,
    "version" INTEGER NOT NULL,
    "config" JSONB NOT NULL,
    "publishedBy" TEXT,
    "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "business_template_versions_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "business_template_versions_templateId_version_key" ON "business_template_versions"("templateId", "version");
ALTER TABLE "business_template_versions" ADD CONSTRAINT "business_template_versions_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "business_templates"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "business_template_requests" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT,
    "text" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'NEW',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "business_template_requests_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "business_template_requests_status_createdAt_idx" ON "business_template_requests"("status", "createdAt");

-- Tablas de plataforma, sin RLS (como plans). Sin DELETE: un rubro se
-- desactiva (isActive), no se borra, porque hay negocios que lo usan.
GRANT SELECT, INSERT, UPDATE ON "business_templates" TO plexo_app;
GRANT SELECT, INSERT ON "business_template_versions" TO plexo_app;
GRANT SELECT, INSERT, UPDATE ON "business_template_requests" TO plexo_app;

-- Catálogo inicial (133 rubros), el mismo de la maqueta aprobada.
-- Después se edita desde /admin/rubros sin tocar código.

SELECT md5('oplex-rubro-v1:' || "id")::uuid::text, "id", 1, "config", 'migración inicial' FROM "business_templates";
